            aCross = (RotL64(aWaterLaneC[((S_BLOCK1 - aIndex + 5009U)) & S_BLOCK1], 37U) ^ RotL64(aWaterLaneA[((S_BLOCK1 - aIndex + 7443U)) & S_BLOCK1], 56U));
