            aCross = (RotL64(aSoilLaneA[((S_BLOCK1 - aIndex + 26228U)) & S_BLOCK1], 5U) ^ RotL64(aLightningLaneA[((S_BLOCK1 - aIndex + 26165U)) & S_BLOCK1], 60U));
