            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0x5D79ABD5171C8FC9ULL) + aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 17U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xE1CE63E391C61C77ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xC62B7A5C0563EBC9ULL), 19U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xD5C6DE6BB9F16C8FULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0x064946113C054F4CULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 13U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x1D77C769B5AC8831ULL), 11U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x3D37B0F45133C8F8ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterD) ^ 0x49E885854FB9CB50ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x444741C90C2A2CD9ULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterH) + 0xFACE15AB3B18475EULL;
