            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0x45D5D0B3B50C7185ULL) ^ aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 129U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xB9BE8E1C18F38311ULL), 37U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterD) + 0x1DE0EB881F63E5FAULL) + aTwistOrbiterUpdateSaltF[(((255U - aIndex) + 68U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0xB7297BD049339106ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xD1EEBB688172B281ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x532F218E23D4447AULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0x04B3CAD50E0EB0BDULL;
            aOrbiterG = RotL64((aOrbiterG * 0x8B5ABE1E1611869BULL), 5U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0xE17B03030D2B060FULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0xBF8E8742EB7F6B83ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x1ED1AEC20A1B3893ULL), 51U);
            //
            aIngress = RotL64(aOrbiterE, 41U) ^ aOrbiterD;
            aIngress = aIngress + (aOrbiterK ^ RotL64(aOrbiterH, 10U));
            aIngress = aIngress + (aOrbiterI ^ RotL64(aOrbiterF, 27U));
            aIngress = aIngress + (RotL64(aOrbiterA, 57U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterG, 37U);
