            //
            aWandererA = aWandererA ^ (((RotL64(aCross, 14U) + RotL64(aOrbiterF, 57U)) + aOrbiterH) + aTwistWandererUpdateSaltA[((aIndex + 42U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aPrevious, 35U) + aOrbiterE) + RotL64(aOrbiterA, 12U));
            aWandererG = aWandererG ^ ((RotL64(aScatter, 23U) + aOrbiterD) + RotL64(aOrbiterI, 35U));
            aWandererE = aWandererE + (((RotL64(aIngress, 57U) + RotL64(aOrbiterE, 3U)) + aOrbiterF) + RotL64(aCarry, 3U));
            aWandererJ = aWandererJ ^ (((RotL64(aScatter, 47U) + aOrbiterE) + RotL64(aOrbiterI, 39U)) + aTwistWandererUpdateSaltB[((aIndex + 177U)) & S_SALT1]);
            aWandererB = aWandererB + (((RotL64(aCross, 4U) + RotL64(aOrbiterG, 28U)) + aOrbiterI) + RotL64(aCarry, 19U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 53U) + RotL64(aOrbiterJ, 43U)) + aOrbiterE);
