            aScatter = (RotL64(aIngress, 20U) ^ RotL64(aCross, 41U)) + (RotL64(aPrevious, 5U) + RotL64(aCarry, 53U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterI = (aWandererF + RotL64(aIngress, 6U)) + 0x42F2CF0130B4ED73ULL;
            aOrbiterF = (aWandererC + RotL64(aCross, 27U)) + 0x9BE8E86DBA8757EDULL;
            aOrbiterJ = (aWandererG + RotL64(aPrevious, 57U)) + 0x5520D02A5A6A033DULL;
            aOrbiterE = (aWandererB + RotL64(aScatter, 35U)) + 0x1A249E3EFCA86C17ULL;
            aOrbiterG = ((aWandererD + RotL64(aPrevious, 41U)) + 0x9E82167F0C40B0D5ULL) + aTwistOrbiterAssignSaltB[(((255U - aIndex) + 242U)) & S_SALT1];
            aOrbiterD = ((aWandererK + RotL64(aIngress, 51U)) + 0x6F679CCA965DE090ULL) + aTwistOrbiterAssignSaltD[((aIndex + 22U)) & S_SALT1];
            aOrbiterH = ((aWandererE + RotL64(aScatter, 11U)) + RotL64(aCarry, 39U)) + 0xB476CE53BD5D9E1CULL;
            aOrbiterA = ((aWandererI + RotL64(aCross, 23U)) + RotL64(aCarry, 5U)) + 0x8C25316463E4DC7EULL;
            aOrbiterB = ((aWandererA + RotL64(aIngress, 18U)) + RotL64(aCarry, 47U)) + 0xC4459D50D3610D47ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0xC120B3F152A64B71ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x0182D62913B581E1ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x16067DDF2E7BFBB9ULL), 23U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0x0BD261B8E177A546ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 145U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterE) ^ 0x7AB8DDD4CA8D67E1ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x60BE405F028529E5ULL), 35U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x856217C752D8E2B3ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x6B31DA3535C5AD53ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xB5DA9A23C8B3297BULL), 53U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xCF68FA6C8675D108ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x5D721186AB1864D7ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xA5BD62445BB8836BULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterG) + 0xBD0D70375BA0F9B6ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0xFDED119ED0FCC8DDULL;
            aOrbiterD = RotL64((aOrbiterD * 0xB4E1D0A6559F732BULL), 39U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterB) + 0xD2EC22A901E5BDCAULL) + aTwistOrbiterUpdateSaltB[(((255U - aIndex) + 201U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x548B8675903AE128ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xCD454726BCBE3BE1ULL), 47U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0xA0808A7D03E734EDULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0xA1EB270521657AE1ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 214U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x7E2234759E0FA71BULL), 13U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x0F4BEF9314FC922AULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x5F690CE5ABA35D18ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 121U)) & S_SALT1];
