            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xBC5CB6EE6B4FA5B7ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterK) ^ 0x9E328ABCF5A49702ULL) ^ aTwistOrbiterUpdateSaltF[((aIndex + 57U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x10655BBAB69920CBULL), 3U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x243D81F42E85FCABULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterA) ^ 0x40CF6DB09B235E20ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x94C9CB18127AD0DDULL), 39U);
            //
