            aOrbiterF = RotL64((aOrbiterF * 0xF05DB6A76EF71327ULL), 53U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0xBBD8A101D9A4F31BULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterE) ^ 0xFDD17D764DF76FCDULL;
