            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x923198C90AB5B7B0ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x026F9DE467CF6E4DULL;
            aOrbiterH = RotL64((aOrbiterH * 0x8341D0B783F05BB9ULL), 19U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x58E7ABDD846A136EULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x2A3928E921B0985EULL;
