            aOrbiterJ = ((aWandererG + RotL64(aScatter, 19U)) + RotL64(aCarry, 23U)) + 0x06CE423D604486A2ULL;
            aOrbiterF = ((aWandererB + RotL64(aIngress, 60U)) + 0x73A4064772EBB7CBULL) + aTwistOrbiterAssignSaltE[((aIndex + 35U)) & S_SALT1];
            aOrbiterI = ((aWandererC + RotL64(aCross, 39U)) + RotL64(aCarry, 51U)) + 0x8E9D55233AC425DDULL;
            aOrbiterK = (aWandererH + RotL64(aScatter, 53U)) + 0x7F5F9B06B496B5B9ULL;
            aOrbiterE = ((aWandererD + RotL64(aIngress, 35U)) + 0x861E0B65D835C7E3ULL) + aTwistOrbiterAssignSaltC[((aIndex + 40U)) & S_SALT1];
