            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0xA3499A9952677B5EULL) + aTwistOrbiterUpdateSaltE[((aIndex + 18U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterF) ^ 0xDC1C9133D513B669ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 225U)) & S_SALT1];
