            aOrbiterJ = (aWandererF + RotL64(aPrevious, 51U)) + 0xBF68251187DF81CEULL;
            aOrbiterD = ((aWandererG + RotL64(aScatter, 23U)) + RotL64(aCarry, 11U)) + 0x6373D55897E8BF2CULL;
            aOrbiterE = (aWandererD + RotL64(aCross, 37U)) + 0x53AC58775CDE63F5ULL;
            aOrbiterI = ((aWandererB + RotL64(aPrevious, 41U)) + 0x2EA9994EA0CD7BC9ULL) + aKeyRotateAOrbiterAssignSaltF[(((255U - aIndex) + 31U)) & S_SALT1];
            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x6AD5066872B0DEFEULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x5C14BDB5F5945FB4ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x65357D183519973FULL), 35U);
