            aOrbiterF = (aOrbiterF + aOrbiterK) + 0x9ECEF2DB6F68E7AEULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0x297D60FBE35077A1ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 102U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x6CC23099FD4E4147ULL), 39U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xA9682A759A63E316ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterD) ^ 0x3E02733C43A58947ULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 35U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x51C949745036DA59ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0xA841758B83EC325BULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterH) ^ 0x0CD71D60F8FD1DCAULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1B799C58BBF38E79ULL), 11U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterI) + 0x9E779B66A9138306ULL) + aKeyRotateAOrbiterUpdateSaltC[(((255U - aIndex) + 54U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0x40421247D4D64BACULL;
